#include <cstdio>

int main() {
    int vp, vd, t, f, c;
    scanf("%d%d%d%d%d", &vp, &vd, &t, &f, &c);

    if (vp >= vd) {
        puts("0");
        return 0;
    }

    int ans = 0;
    double position = static_cast<double>(t) * vp;

    while (position < c) {
        double catchTime = position / (vd - vp);
        position += catchTime * vp;

        if (position >= c)
            break;

        ++ans;
        position += vp * (catchTime + f);
    }

    printf("%d\n", ans);
    return 0;
}

