double Prin;

int main() {
    scanf("%d%d%d%d%d", &vp, &vd, &t, &f, &c);

    Prin = 1.0 * t * vp;

    if (vp >= vd) {
        puts("0");
        return 0;
    }

    while (Prin < c) {
        double next = Prin / (vd - vp);
        Prin += next * vp;

        if (Prin >= c)
            break;

        ans++;
        next += f;
        Prin += vp * next;
    }

    printf("%d\n", ans);
    return 0;
}

